{
  "contract": "WAsgard",
  "closure": {
    "site_function": "wrap",
    "site_call": ".transferFrom",
    "functions": ["wrap"],
    "justification": "wrap is the only function that modifies 'deposits' and 'lastWrapped' during the callback window."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [],
    "nesting_bound": {
      "wrap": 1
    }
  },
  "phases": {
    "function": "wrap",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .transferFrom"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .transferFrom",
      "to_marker": "after .transferFrom"
    },
    "post": {
      "name": "post",
      "from_marker": "after .transferFrom",
      "to_marker": "exit"
    },
    "linearization_point": "after .transferFrom"
  },
  "ghost_state": [
    {
      "name": "_sum__balances",
      "sol_type": "uint256",
      "meaning": "Sum of all balances in the system",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__balances == _totalSupply",
    "stable_formula": "_sum__balances == _totalSupply",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__balances == _totalSupply",
    "rule": "The sum of all balances must equal the total supply at all times."
  }
}
